-- 0003: database-level append-only protection for clinically relevant history.
--
-- Rules enforced here (not only in application code):
--   finding_versions, reviews, correspondence_decisions, audit_events
--     * UPDATE is refused.
--     * TRUNCATE is refused.
--     * A DIRECT DELETE of a row is refused.
--   Rows may still disappear when their parent patient is deleted (ON DELETE CASCADE).
--   That path is kept on purpose: a whole-record erasure (for example a data-erasure
--   request, or the admin "reset synthetic workspace") must stay possible. It is the
--   only way history can be removed, and it removes the whole patient, not one version.
--
-- How a cascade is told apart from a direct delete: pg_trigger_depth().
-- A direct DELETE fires this trigger at depth 1. A delete fired by the foreign-key
-- cascade runs inside another trigger, so the depth is 2 or more.
--
-- Limits (honest):
--   * A database superuser or the table owner can still drop the trigger. This guards
--     against application bugs and ordinary roles, not against a privileged operator.
--   * audit_events has no foreign key to patients, so it is never removed by cascade.
--     Nothing in the app deletes audit rows any more.

create or replace function ab_block_mutation() returns trigger
language plpgsql as $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'append-only: % cannot be updated (row %). Insert a new row instead.', tg_table_name, old.id
      using errcode = 'restrict_violation';
  elsif tg_op = 'DELETE' then
    if pg_trigger_depth() <= 1 then
      raise exception 'append-only: % rows cannot be deleted directly (row %).', tg_table_name, old.id
        using errcode = 'restrict_violation';
    end if;
    return old;
  end if;
  return null;
end;
$$;

create or replace function ab_block_truncate() returns trigger
language plpgsql as $$
begin
  raise exception 'append-only: % cannot be truncated.', tg_table_name
    using errcode = 'restrict_violation';
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['finding_versions', 'reviews', 'correspondence_decisions', 'audit_events']
  loop
    execute format('drop trigger if exists %I on %I', t || '_append_only', t);
    execute format(
      'create trigger %I before update or delete on %I for each row execute function ab_block_mutation()',
      t || '_append_only', t);
    execute format('drop trigger if exists %I on %I', t || '_no_truncate', t);
    execute format(
      'create trigger %I before truncate on %I for each statement execute function ab_block_truncate()',
      t || '_no_truncate', t);
  end loop;
end $$;


-- 0004: store the year of the first period (menarche) on the patient record.
--
-- Why: the 2023 international PCOS guideline defines irregular cycles, and when
-- ovarian ultrasound may be used, by time since the first period. Until now the
-- app only had year of birth and used its own age-20 line instead.
--
-- Data minimisation: a YEAR only, never a full date. The app treats the result as
-- uncertain by up to one year either way (see src/lib/clinic/pcos-context.ts).
--
-- Nullable on purpose: unknown stays unknown. Nothing is back-filled or guessed.
-- Changes are written through setMenarcheYear, which records the previous value in
-- audit_events (append-only since 0003), so an earlier value is never silently lost.

alter table patients add column if not exists menarche_year integer;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'patients_menarche_year_range'
  ) then
    alter table patients
      add constraint patients_menarche_year_range
      check (menarche_year is null or menarche_year between 1900 and 2200);
  end if;
end $$;


-- 0005: uploaded clinical reports (TXT / DOCX / PDF) and source-anchored evidence quotes.
--
-- Data minimisation:
--   * The original file never reaches the server. The browser extracts text, de-identifies it, shows the
--     redacted preview, and sends only the confirmed de-identified text plus a SHA-256 of the original file.
--   * The server runs de-identification again before storing (it does not trust the client).
--   * Redactions are stored as kind + length only. Removed values are never stored.
--
-- Provenance:
--   * report_extractions keeps the extractor id, the de-identification method and the full structured
--     extraction JSON, so every extracted item can be traced to [start, end) offsets in reports.body.
--   * evidence_links gains quote_start / quote_end. A report quote is saved only after the server checks that
--     reports.body.slice(start, end) equals the quote exactly.

alter table reports add column if not exists source_kind text not null default 'seeded';

create table if not exists report_extractions (
  id text primary key,
  user_id text not null,
  report_id text not null references reports (id) on delete cascade,
  file_name text not null,
  file_kind text not null check (file_kind in ('txt', 'docx', 'pdf')),
  content_sha256 text not null check (content_sha256 ~ '^[0-9a-f]{64}$'),
  deid_method text not null,
  redaction_count integer not null check (redaction_count >= 0),
  redaction_kinds text not null,
  extractor text not null,
  extraction text not null,
  warnings text not null,
  created_at timestamptz not null default now()
);
create index if not exists report_extractions_report_idx on report_extractions (report_id);
create index if not exists report_extractions_user_idx on report_extractions (user_id, created_at);

alter table evidence_links add column if not exists quote_start integer;
alter table evidence_links add column if not exists quote_end integer;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'evidence_links_quote_range') then
    alter table evidence_links
      add constraint evidence_links_quote_range
      check (
        (quote_start is null and quote_end is null)
        or (quote_start >= 0 and quote_end > quote_start)
      );
  end if;
end $$;


